import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { inflateSync } from 'node:zlib';
import { pathToFileURL } from 'node:url';
import * as transport from './fal_sheet_transport.mjs';
// Regional offline evidence is the reviewed official byte snapshot, not a live quote.
const REGIONAL_SCHEMA = inflateSync(Buffer.from('', 'base64'));
const { runCommand, validateEndpointPricingEvidence, validateEndpointInvalidResultEvidence } = transport;


const MODEL = 'fal-ai/ideogram/remove-background';
const VACE = 'fal-ai/wan-vace-14b/inpainting';
// Pricing paragraph below transcribes the visible official archived paragraph; full-page verification is logged externally.

const NOW = 1_800_000_000_000;
const hash = bytes => createHash('sha256').update(bytes).digest('hex');
const json = value => new Response(JSON.stringify(value), {status:200});
function png() { const b=Buffer.alloc(33); Buffer.from('89504e470d0a1a0a','hex').copy(b); b.writeUInt32BE(13,8); b.write('IHDR',12); b.writeUInt32BE(64,16); b.writeUInt32BE(64,20); b[24]=8;b[25]=6;return b; }
function fixture() {
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'task-transport-'));
  const source=path.join(dir,'source.png');fs.writeFileSync(source,png());
  const context={task_ref:{schema:'sprite_task_ref_v1',task_id:'task',task_manifest:path.join(dir,'task.json'),authorization_sha256:'a'.repeat(64),target_id:'target'},run_manifest:path.join(dir,'run-manifest.json'),run_id:'run',attempt_id:'run:attempt-01',operation_id:'run:attempt-01:primary'};
  const config={schema_version:3,model:MODEL,source:{path:source,sha256:hash(png())},input:{sync_mode:false},authorization:{request_authorized:true,scope_sha256:'b'.repeat(64),task_context:context},max_cost_usd:1};
  fs.writeFileSync(path.join(dir,'config.json'),JSON.stringify(config,null,2).replace('"max_cost_usd": 1','"max_cost_usd": 1.0'));
  return {dir,config,context};
}
function bridge(c,{id=null,started=false,allow=true,hook=null}={}) {
  return async (command,payload)=>{
    if(hook)await hook(command,payload);
    return {state:command==='check-context'?'CONTEXT_VERIFIED':'SUBMISSION_AUTHORIZED',task_id:'task',target_id:'target',run_id:'run',attempt_id:'run:attempt-01',operation_id:c.context.operation_id,config_sha256:payload.config_sha256,config_file_sha256:payload.config_file_sha256,binding_sha256:'c'.repeat(64),provider_request_id:id,submission_started:command==='before-submit'||started,status:started?'committed':'held',outcome_status:started?'uncertain':null,...(command==='before-submit'?{submit_allowed:allow}:{})};
  };
}
async function price(c,unit='0.02') {return runCommand('pricing',c.dir,{key:'fake-key',now:()=>NOW,fetchImpl:async()=>json({prices:[{endpoint_id:MODEL,currency:'USD',unit:'image',unit_price:unit}]})});}
function planFixture() {
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'task-plan-'));
  const plan={schema:'sprite_deferred_cleanup_v1',primary_operation_id:'run:attempt-01:primary',primary_config_sha256:'d'.repeat(64),model:MODEL,input:{sync_mode:false},reserved_units:1,source_from:'primary_raw_png',source_limits:{mime:'image/png',max_bytes:10485760,max_width:4096,max_height:4096}};
  fs.writeFileSync(path.join(dir,'plan.json'),JSON.stringify(plan,null,2)+'\n');return {dir,plan};
}

test('planning quote archives actual API evidence without an image and cannot execute',async()=>{
  const c=planFixture();const result=await runCommand('pricing-plan',c.dir,{key:'fake-key',now:()=>NOW,fetchImpl:async()=>json({prices:[{endpoint_id:MODEL,currency:'USD',unit:'images',unit_price:'0.0200'}]})});
  assert.equal(result.state,'PRICED'); assert.equal(result.quote.estimated_cost_usd_decimal,'0.02');assert.equal(result.quote.plan_sha256,hash(fs.readFileSync(path.join(c.dir,'plan.json'))));
  assert.equal(fs.existsSync(path.join(c.dir,'pricing-receipts')),false);
  const receipt=JSON.parse(fs.readFileSync(result.quote.receipt_path));assert.equal(receipt.schema,'sprite_cleanup_planning_quote_v1');assert.equal(receipt.reserved_units,1);assert.equal(receipt.sources.length,1);
  assert.equal(hash(fs.readFileSync(result.quote.receipt_path)),result.quote.receipt_sha256);
  assert.equal((await runCommand('execute',c.dir,{key:'fake-key',fetchImpl:async()=>{throw Error('no network');}})).state,'BLOCKED');
});

test('planning rejects unsupported price units and altered plan with no executable claim',async()=>{
  for(const mutate of [p=>p.source_limits.max_bytes++,p=>p.reserved_units++,p=>p.input.sync_mode=true,p=>p.source_from='replacement']){
    const c=planFixture();mutate(c.plan);fs.writeFileSync(path.join(c.dir,'plan.json'),JSON.stringify(c.plan));let calls=0;
    const r=await runCommand('pricing-plan',c.dir,{key:'fake',fetchImpl:async()=>{calls++;throw Error('must not fetch');}});assert.equal(r.state,'BLOCKED');assert.equal(calls,0);
  }
  const c=planFixture();const r=await runCommand('pricing-plan',c.dir,{key:'fake',fetchImpl:async()=>json({prices:[{endpoint_id:MODEL,currency:'USD',unit:'seconds',unit_price:'0.02'}]})});assert.equal(r.block_reason,'PRICE_NOT_VERIFIABLE');
});

