  assert.equal(result.quote.estimated_cost_usd_decimal,'0.010000000001');assert.notEqual(result.quote.config_sha256,result.quote.config_file_sha256);assert.equal(result.quote.config_file_sha256,hash(fs.readFileSync(path.join(c.dir,'config.json'))));
