test('managed hook follows key/receipt/cap gates and precedes durable claim/POST',async()=>{
  const c=fixture();await price(c);const events=[];
  const taskBridge=bridge(c,{hook:(command,payload)=>{events.push(command);assert.equal(fs.existsSync(path.join(c.dir,'submission.claim')),false);if(command==='before-submit'){assert.equal(payload.amount_usd,'0.02');assert.match(payload.quote_sha256,/^[a-f0-9]{64}$/);}}});
  const r=await runCommand('execute',c.dir,{key:'fake',now:()=>NOW+1,taskBridge,fetchImpl:async(_u,init)=>{events.push(init.method);if(init.method==='POST'){assert.equal(fs.existsSync(path.join(c.dir,'submission.claim')),true);return json({request_id:'req-one'});}return json({status:'IN_QUEUE'});}});
  assert.equal(r.state,'IN_QUEUE');assert.deepEqual(events,['check-context','before-submit','POST','GET']);
});

test('missing key, stale or invalid receipt and local cap never invoke before-submit',async()=>{
  for(const gate of ['key','stale','invalid','cap']){
    const c=fixture();if(gate==='cap'){c.config.max_cost_usd=.01;fs.writeFileSync(path.join(c.dir,'config.json'),JSON.stringify(c.config));}const priced=await price(c);if(gate==='invalid')fs.appendFileSync(priced.quote.receipt_path,'x');let hooks=0;let network=0;
    const r=await runCommand('execute',c.dir,{key:gate==='key'?'':'fake',now:()=>gate==='stale'?NOW+900001:NOW+1,taskBridge:bridge(c,{hook:cmd=>{if(cmd==='before-submit')hooks++;}}),fetchImpl:async()=>{network++;throw Error('no');}});
    assert.equal(r.state,gate==='key'?'KEY_SETUP_REQUIRED':'BLOCKED');assert.equal(hooks,0);assert.equal(network,0);assert.equal(fs.existsSync(path.join(c.dir,'submission.claim')),false);
  }
});

