  r=await runCommand('execute',c.dir,{key:'fake',taskBridge:bridge(c,{started:true}),fetchImpl:async()=>{network++;}});assert.equal(r.state,'SUBMISSION_STATUS_UNKNOWN');assert.equal(network,0);
