test('fixed Python subprocess isolates secrets and rejects oversized or malformed stdout before POST',async()=>{
  const installation=fs.mkdtempSync(path.join(os.tmpdir(),'transport-install-'));
  for(const file of ['fal_sheet_transport.mjs','sheet_video_metadata.mjs'])fs.copyFileSync(new URL(file,import.meta.url),path.join(installation,file));
  const {pathToFileURL}=await import('node:url');const isolated=await import(pathToFileURL(path.join(installation,'fal_sheet_transport.mjs')).href);
  const script=path.join(installation,'sprite_task_bridge.py');
  const healthy=`import json,sys,os\np=json.load(sys.stdin)\nassert not any(k in os.environ for k in ['FAL_KEY','PYTHONPATH','PYTHONHOME','NODE_OPTIONS'])\nc=json.load(open(os.path.join(p['job_dir'],'config.json')))['authorization']['task_context']\ncommand=sys.argv[1]\nr=dict(state='CONTEXT_VERIFIED' if command=='check-context' else 'SUBMISSION_AUTHORIZED',task_id=c['task_ref']['task_id'],target_id=c['task_ref']['target_id'],run_id=c['run_id'],attempt_id=c['attempt_id'],operation_id=c['operation_id'],config_sha256=p['config_sha256'],config_file_sha256=p['config_file_sha256'],binding_sha256='c'*64,provider_request_id=None,submission_started=command=='before-submit',status='held',outcome_status=None)\nif command=='before-submit':r['submit_allowed']=True\nprint(json.dumps(r))\n`;
  const previous=Object.fromEntries(['FAL_KEY','PYTHONPATH','PYTHONHOME','NODE_OPTIONS'].map(k=>[k,process.env[k]]));
  try{
    for(const k of Object.keys(previous))process.env[k]='fake-private-must-not-propagate';
    for(const [body,expected] of [[healthy,'IN_QUEUE'],["print('x'*70000)\n",'BLOCKED'],["print('{} {}')\n",'BLOCKED']]){
      fs.writeFileSync(script,body);const c=fixture();await price(c);let posts=0;
      const r=await isolated.runCommand('execute',c.dir,{key:'fake',now:()=>NOW+1,fetchImpl:async(_u,i)=>{if(i.method==='POST'){posts++;return json({request_id:'fixed-process'});}return json({status:'IN_QUEUE'});}});
      assert.equal(r.state,expected);assert.equal(posts,expected==='IN_QUEUE'?1:0);if(expected==='BLOCKED')assert.equal(fs.existsSync(path.join(c.dir,'submission.claim')),false);
    }
  }finally{for(const[k,v]of Object.entries(previous)){if(v===undefined)delete process.env[k];else process.env[k]=v;}}
});

