  const files={edit:path.join(runRoot,'snapshots','edit.png'),identity:path.join(runRoot,'snapshots','identity.png'),a:path.join(runRoot,'snapshots','endpoint-a.png'),b:path.join(attemptRoot,'pose_edit','raw.png'),grid:path.join(attemptRoot,'cycle-grid.png')};
  fs.mkdirSync(path.dirname(files.b),{recursive:true});Object.entries(files).forEach(([k,p],i)=>fs.writeFileSync(p,endpointPng(k==='grid'?2880:2048,k==='grid'?1440:2048,i+1)));
  const inputRoles=role==='pose_edit'?['edit','identity']:role==='cleanup'?['grid']:['start','end'];
  const inputPaths=role==='pose_edit'?[files.edit,files.identity]:role==='cleanup'?[files.grid]:role==='video_ab'?[files.a,files.b]:[files.b,files.a];
  const inputFiles=inputRoles.map((r,i)=>({role:r,path:inputPaths[i],sha256:hash(fs.readFileSync(inputPaths[i]))}));
  const context={task_ref:{schema:'sprite_task_ref_v1',task_id:'task',task_manifest:path.join(runRoot,'task.json'),authorization_sha256:'a'.repeat(64),target_id:'target'},run_manifest:path.join(runRoot,'run-manifest.json'),run_id:'run',attempt_id:'run:attempt-01',operation_id:`run:attempt-01:${role}`};
  const input=role==='pose_edit'?{prompt:'repair material retaining the opposite pose',resolution:'2K',aspect_ratio:'1:1',num_images:1,output_format:'png',limit_generations:true,enable_web_search:false,sync_mode:false,safety_tolerance:'4'}:role==='cleanup'?{sync_mode:false}:{prompt:'one half run cycle left',frames:81,fps:24,resolution:'720p',aspect_ratio:'1:1',steps:30,acceleration:'none',prompt_expansion:false,enable_safety_checker:true};
  const config={schema_version:4,route:'endpoint_cycle_v1',role,model:endpointModel(role),input_files:inputFiles,input,authorization:{request_authorized:true,task_context:context},max_cost_usd:1};
  const plan={schema:'sprite_endpoint_plan_v1',attempt_id:context.attempt_id,source_sha256:'d'.repeat(64),pose_config_sha256:role==='pose_edit'?hash(encoded(config)):'c'.repeat(64),pose_inputs:['edit','identity'].map(r=>({role:r,sha256:hash(fs.readFileSync(files[r]))})),endpoint_a_sha256:hash(fs.readFileSync(files.a)),preparation_policy:'pose_canvas_2048_v1',video_policy:{frames:81,fps:24,resolution:'720p',aspect_ratio:'1:1',steps:30,acceleration:'none',prompt_expansion:false},sampling_policy:'endpoint_full_range_81_four_phases_v1',cleanup_policy:{model:MODEL,sync_mode:false,max_bytes:10485760,max_width:4096,max_height:4096},output_policy:{frames:8,frame_ms:100,loop:true,canvas:[2048,2048],geometry_policy:'common_nearest_2048_v1',alignment_policy:'body_x_preserve_y_v1'}};
  fs.writeFileSync(path.join(runRoot,'endpoint-plan.json'),encoded(plan));
  const inputs=inputFiles.map(({role,sha256})=>({role,sha256}));fs.writeFileSync(path.join(dir,'inputs.json'),encoded(inputs));
  const kind=role==='pose_edit'?'pose_edit_inputs':role==='cleanup'?'two_video_full_range_grid':'ordered_endpoint_pair';
  const evidence=role==='pose_edit'?{preparation_proof_sha256:'e'.repeat(64),original_ref:{path:path.join(runRoot,'snapshots','source-original.png'),sha256:'d'.repeat(64)},b_candidate_ref:{path:path.join(runRoot,'snapshots','b-candidate-original.png'),sha256:'f'.repeat(64)}}:role==='cleanup'?{ab_operation_id:'run:attempt-01:video_ab',ab_request_id:'ab-id',ab_raw_sha256:'e'.repeat(64),ba_operation_id:'run:attempt-01:video_ba',ba_request_id:'ba-id',ba_raw_sha256:'f'.repeat(64),cycle_gate_sha256:'b'.repeat(64),selection_sha256:'a'.repeat(64),grid_sha256:inputFiles[0].sha256}:{pose_operation_id:'run:attempt-01:pose_edit',pose_request_id:'pose-id',pose_raw_sha256:hash(fs.readFileSync(files.b)),pair_gate_sha256:'b'.repeat(64),direction:role==='video_ab'?'ab':'ba'};
