function endpointBridge(c,{id=null,started=false,mutate=null,hook=null}={}){
  return async(command,payload)=>{
    if(hook)await hook(command,payload);
    assert.equal(payload.schema,command==='check-context'?'sprite_transport_context_v2':'sprite_before_submit_v2');assert.equal(payload.input_set_sha256,hash(encoded(c.inputs)));assert.equal(payload.source_sha256,undefined);
    if(command==='before-submit')assert.equal(payload.experiment_state_sha256,'7'.repeat(64));
    const result={schema:'sprite_transport_context_result_v2',state:command==='check-context'?'CONTEXT_VERIFIED':'SUBMISSION_AUTHORIZED',task_id:'task',target_id:'target',run_id:'run',attempt_id:'run:attempt-01',operation_id:c.context.operation_id,config_sha256:payload.config_sha256,config_file_sha256:payload.config_file_sha256,input_set_sha256:payload.input_set_sha256,binding_sha256:'c'.repeat(64),experiment_state_sha256:(command==='check-context'?'7':'8').repeat(64),provider_request_id:id,submission_started:started||command==='before-submit',status:started?'committed':'held',outcome_status:null,...(command==='before-submit'?{submit_allowed:true}:{})};
    if(mutate)mutate(result,command);return result;
  };
}
function wanHtml(base='0.40'){return `<html><head><link rel="canonical" href="https://fal.ai/models/${FLF}"></head><body><p>For a video generation, your request will cost $0.20 at 480p resolution and $${base} at 720p resolution. For $1 you can generate 5 videos at 480p or 2 at 720p with the default frames. More than the default frames will cost 1.25x more.</p></body></html>`;}
async function endpointPrice(c,{unit,base,at=NOW,schema,publicBody}={}){
  const model=c.config.model;
  return runCommand('pricing',c.dir,{key:'fake',now:()=>at,fetchImpl:async url=>{
    if(String(url).startsWith('https://api.fal.ai/'))return json({prices:[{endpoint_id:model,currency:'USD',unit:unit??(model===FLF?'videos':'images'),unit_price:base??(model===FLF?'0.40':model===MODEL?'0.01':'0.08')}]});
    if(String(url).startsWith('https://fal.ai/api/openapi/'))return new Response(schema??ENDPOINT_SCHEMAS[model]);
    return new Response(publicBody??(model===FLF?wanHtml():nanoHtml('0.08')));
  }});
}

