function endpointMp4({duration=3.375,width=720,height=720}={}){
  const box=(type,bytes)=>{const b=Buffer.alloc(8+bytes.length);b.writeUInt32BE(b.length);b.write(type,4);bytes.copy(b,8);return b;};
  const ftyp=box('ftyp',Buffer.from('69736f6d0000020069736f6d69736f32','hex'));const mvhd=Buffer.alloc(100);mvhd.writeUInt32BE(24000,12);mvhd.writeUInt32BE(Math.round(duration*24000),16);const tkhd=Buffer.alloc(84);tkhd.writeUInt32BE(width*65536,76);tkhd.writeUInt32BE(height*65536,80);const hdlr=Buffer.alloc(20);hdlr.write('vide',8);
  return Buffer.concat([ftyp,box('moov',Buffer.concat([box('mvhd',mvhd),box('trak',Buffer.concat([box('tkhd',tkhd),box('mdia',box('hdlr',hdlr))]))]))]);
}
async function endpointDownload(c,{bytes,body}={}){
  await endpointPrice(c);
  return runCommand('execute',c.dir,{key:'fake',now:()=>NOW+1,taskBridge:endpointBridge(c),fetchImpl:async(url,init)=>{
    if(init.method==='POST')return json({request_id:'endpoint-download'});
    if(String(url).endsWith('/status?logs=0'))return json({status:'COMPLETED'});
    if(String(url).includes('/requests/'))return json(body??(c.config.role==='pose_edit'?{images:[{url:'https://fal.media/endpoint.png'}]}:c.config.role==='cleanup'?{image:{url:'https://fal.media/endpoint.png'}}:{video:{url:'https://fal.media/endpoint.mp4'}}));
    assert.equal(init.headers.Authorization,undefined);return new Response(bytes??(c.config.role.startsWith('video')?endpointMp4():fs.readFileSync(c.config.role==='cleanup'?c.files.grid:c.files.edit)));
  }});
}

