test('endpoint fixed Python subprocess uses v2 identity and sanitized environment and rejects malformed response',async()=>{
  const installation=fs.mkdtempSync(path.join(os.tmpdir(),'endpoint-install-'));for(const file of ['fal_sheet_transport.mjs','sheet_video_metadata.mjs'])fs.copyFileSync(new URL(file,import.meta.url),path.join(installation,file));const {pathToFileURL}=await import('node:url');const isolated=await import(pathToFileURL(path.join(installation,'fal_sheet_transport.mjs')).href);const script=path.join(installation,'sprite_task_bridge.py');
  const healthy=`import json,sys,os\np=json.load(sys.stdin)\nassert not any(k in os.environ for k in ['FAL_KEY','PYTHONPATH','PYTHONHOME','NODE_OPTIONS'])\nc=json.load(open(os.path.join(p['job_dir'],'config.json')))['authorization']['task_context']\ncmd=sys.argv[1]\nassert p['schema']==('sprite_transport_context_v2' if cmd=='check-context' else 'sprite_before_submit_v2')\nif cmd=='before-submit':assert p['experiment_state_sha256']=='7'*64\nr=dict(schema='sprite_transport_context_result_v2',state='CONTEXT_VERIFIED' if cmd=='check-context' else 'SUBMISSION_AUTHORIZED',task_id=c['task_ref']['task_id'],target_id=c['task_ref']['target_id'],run_id=c['run_id'],attempt_id=c['attempt_id'],operation_id=c['operation_id'],config_sha256=p['config_sha256'],config_file_sha256=p['config_file_sha256'],input_set_sha256=p['input_set_sha256'],binding_sha256='c'*64,experiment_state_sha256=('7' if cmd=='check-context' else '8')*64,provider_request_id=None,submission_started=cmd=='before-submit',status='held',outcome_status=None)\nif cmd=='before-submit':r['submit_allowed']=True\nprint(json.dumps(r))\n`;
  const previous=Object.fromEntries(['FAL_KEY','PYTHONPATH','PYTHONHOME','NODE_OPTIONS'].map(k=>[k,process.env[k]]));
  try{for(const key of Object.keys(previous))process.env[key]='private-test-must-not-propagate';for(const [body,expected]of [[healthy,'IN_QUEUE'],["print('{} {}')\n",'BLOCKED']]){fs.writeFileSync(script,body);const c=endpointFixture();await endpointPrice(c);let posts=0;const r=await isolated.runCommand('execute',c.dir,{key:'fake',now:()=>NOW+1,fetchImpl:async(_u,i)=>i.method==='POST'?(posts++,json({request_id:'fixed-v2'})):json({status:'IN_QUEUE'})});assert.equal(r.state,expected,r.block_reason);assert.equal(posts,expected==='IN_QUEUE'?1:0);}}finally{for(const[k,v]of Object.entries(previous)){if(v===undefined)delete process.env[k];else process.env[k]=v;}}
});

