  const p=JSON.parse(fs.readFileSync(path.join(c.dir,'source-provenance.json')));p.schema='sprite_endpoint_provenance_v2';p.input_set_sha256=hash(encoded(c.inputs));p.endpoint_plan_sha256=hash(encoded(c.plan));
