async function replaySeedreamCapture(c) {
  let gets=0,posts=0;
  const result=await runCommand('execute',c.dir,{key:'fake',taskBridge:endpointBridge(c,{id:'seedream-id',started:true}),fetchImpl:async(url,init)=>{
    if(init.method==='POST'){posts++;throw Error('unexpected second POST');}gets++;
    if(String(url).endsWith('/status?logs=0'))return json({status:'COMPLETED',request_id:'seedream-id'});
    if(String(url).includes('/requests/'))return json({images:[{url:'https://fal.media/seedream.jpg'}]});
    return new Response(Buffer.from('complete-provider-jpeg-fixture'),{headers:{'content-type':'image/jpeg'}});
  }});
  return {result,gets,posts};
}
for(const targetName of ['status.body','result.body','provider-raw.bin','complete.json']) {
  test(`Seedream atomic publication recovers interrupted first write of ${targetName} from the same ID`,async()=>{
    const c=seedreamFixture();const open=fs.openSync,write=fs.writeFileSync;let targetFd=null,injected=false,injectedPath=null;
    fs.openSync=function(file,flags,...rest){const fd=open(file,flags,...rest);const base=path.basename(String(file));if(flags==='wx' && String(file).startsWith(c.dir) && (base===targetName || (base.startsWith(`.${targetName}.`) && base.endsWith('.partial')))){targetFd=fd;injectedPath=String(file);}return fd;};
    fs.writeFileSync=function(file,data,...rest){if(file===targetFd && !injected){injected=true;write(file,Buffer.from(data).subarray(0,1));const error=Error('injected interrupted publication');error.code='EIO';throw error;}return write(file,data,...rest);};
    let first;
    try{first=(await seedreamDownload(c)).response;}finally{fs.openSync=open;fs.writeFileSync=write;}
    assert.equal(injected,true);assert.equal(first.state,'BLOCKED');
    const {result,gets,posts}=await replaySeedreamCapture(c);assert.equal(posts,0);assert.equal(result.state,'SEEDREAM_CAPTURED',result.block_reason);assert.equal(gets,3);
    const final=path.join(c.dir,targetName==='provider-raw.bin'?targetName:path.join('capture',targetName));
    assert.notEqual(injectedPath,final);assert.equal(fs.existsSync(injectedPath),false);
    assert.equal(transport.validateSeedreamCaptureEvidence(...seedreamCaptureArgs(c)).result_class,'one_image');
  });
}
