test('regional coherent authorization snapshot mutation blocks POST and preserves marker for UNKNOWN resume',async()=>{
 for(const variant of ['scope-authorization','manifest-only']){
  const c=regionalFixture();assert.equal((await regionalPrice(c)).state,'PRICED');
  const marker=path.join(c.dir,'mock-regional-marker.json');let posts=0,markers=0;
  const taskBridge=async(command,payload)=>regionalBridge(c,{started:fs.existsSync(marker),hook:cmd=>{
   if(cmd!=='before-submit')return;
   markers++;fs.writeFileSync(marker,encoded({submission_started:true,operation_id:c.context.operation_id,regional_state_sha256:'8'.repeat(64)}));
   if(variant==='scope-authorization'){
    c.scope.authorization.request_authorized=false;
    fs.writeFileSync(path.join(c.runRoot,'scope.json'),encoded(c.scope));fs.writeFileSync(path.join(c.runRoot,'scope.sha256'),hash(encoded(c.scope))+'\n');
    fs.writeFileSync(path.join(c.runRoot,'run-manifest.json'),encoded({schema_version:3,...c.scope,mode:'whole_sheet',authorization_scope_sha256:hash(encoded(c.scope))}));
   }else{
    const file=path.join(c.runRoot,'run-manifest.json'),manifest=JSON.parse(fs.readFileSync(file));manifest.state='MARKER_MIRRORED';fs.writeFileSync(file,encoded(manifest));
   }
  }})(command,payload);
  const fetchImpl=async(_u,i)=>{if(i.method==='POST'){posts++;return json({request_id:'must-not-submit-scope'});}return json({status:'IN_QUEUE'});};
  const first=await runCommand('execute',c.dir,{key:'fake',now:()=>NOW+1,taskBridge,fetchImpl});
  assert.equal(first.state,'BLOCKED',variant);assert.equal(first.block_reason,'TASK_CONTEXT_CONFLICT',variant);assert.equal(posts,0,variant);assert.equal(markers,1,variant);
  assert.equal(fs.existsSync(path.join(c.dir,'submission.claim')),false,variant);const durableMarker=fs.readFileSync(marker);
  const resumed=await runCommand('execute',c.dir,{key:'fake',now:()=>NOW+2,taskBridge,fetchImpl});
  assert.equal(resumed.state,'SUBMISSION_STATUS_UNKNOWN',variant);assert.equal(resumed.block_reason,'SUBMISSION_CLAIM_WITHOUT_REQUEST_ID',variant);assert.equal(posts,0,variant);assert.equal(markers,1,variant);assert.deepEqual(fs.readFileSync(marker),durableMarker,variant);
 }
});

function resealRegional(c) {
 fs.writeFileSync(path.join(c.dir,'config.json'),encoded(c.config));if(c.config.role==='primary')c.plan.primary_config_sha256=hash(encoded(c.config));fs.writeFileSync(path.join(c.runRoot,'regional-plan.json'),encoded(c.plan));c.scope.request.regional_plan_sha256=hash(encoded(c.plan));fs.writeFileSync(path.join(c.runRoot,'scope.json'),encoded(c.scope));fs.writeFileSync(path.join(c.runRoot,'scope.sha256'),hash(encoded(c.scope))+'\n');fs.writeFileSync(path.join(c.runRoot,'run-manifest.json'),encoded({schema_version:3,...c.scope,mode:'whole_sheet',authorization_scope_sha256:hash(encoded(c.scope))}));
}
