function reorderSchemaObjects(value) {
 if(Array.isArray(value))return value.map(reorderSchemaObjects);
 if(value!==null&&typeof value==='object')return Object.fromEntries(Object.keys(value).reverse().map(k=>[k,reorderSchemaObjects(value[k])]));
 return value;
}

function schemaNumberRepresentation(property,key,lexeme) {
 const document=JSON.parse(REGIONAL_SCHEMA),block=document.components.schemas.WanVace14bInpaintingInput.properties[property],original=JSON.stringify(block),needle=JSON.stringify(key)+':'+JSON.stringify(block[key]);
 assert.ok(original.includes(needle));const changed=original.replace(needle,JSON.stringify(key)+':'+lexeme),source=JSON.stringify(document),target=JSON.stringify(property)+':'+original;assert.ok(source.includes(target));return Buffer.from(source.replace(target,JSON.stringify(property)+':'+changed));
}

function verifySchemaBytes(bytes) {return transport.validateRegionalPricingEvidence(VACE,encoded({prices:[{endpoint_id:VACE,currency:'USD',unit:'seconds',unit_price:'0.08'}]}),Buffer.from(regionalHtml()),bytes);}

test('regional schema numeric pin rejects reviewed shift minimum rounding collision',()=>{
 const base=JSON.parse(REGIONAL_SCHEMA);assert.equal(base.components.schemas.WanVace14bInpaintingInput.properties.shift.minimum,1);
 const changed=schemaNumberRepresentation('shift','minimum','1.00000000000000001');assert.notEqual(changed.toString(),JSON.stringify(base));assert.deepEqual(JSON.parse(changed),base);
 assert.throws(()=>verifySchemaBytes(changed),{code:'PRICE_NOT_VERIFIABLE'});
});

test('regional schema numeric pin rejects underflow collision with an existing zero',()=>{
 const base=JSON.parse(REGIONAL_SCHEMA);assert.equal(base.components.schemas.WanVace14bInpaintingInput.properties.num_interpolated_frames.minimum,0);
 for(const token of ['1e-400','1e-9007199254740993']){const changed=schemaNumberRepresentation('num_interpolated_frames','minimum',token);assert.deepEqual(JSON.parse(changed),base);assert.throws(()=>verifySchemaBytes(changed),{code:'PRICE_NOT_VERIFIABLE'});}
});

test('regional schema numeric pin accepts exactly equivalent decimal and zero representations',()=>{
 const expected=verifySchemaBytes(REGIONAL_SCHEMA);
 for(const token of ['1','1.0','1e0','1E+0','10e-1','0.01e2'])assert.deepEqual(verifySchemaBytes(schemaNumberRepresentation('shift','minimum',token)),expected,token);
 for(const token of ['0','-0','0.0','0e0','0e1000','-0.000e-1000','0e9007199254740993'])assert.deepEqual(verifySchemaBytes(schemaNumberRepresentation('num_interpolated_frames','minimum',token)),expected,token);
});

test('regional schema canonical pin accepts only equivalent serialization',()=>{
 const api=encoded({prices:[{endpoint_id:VACE,currency:'USD',unit:'seconds',unit_price:'0.08'}]}),html=Buffer.from(regionalHtml());
 const verify=bytes=>transport.validateRegionalPricingEvidence(VACE,api,html,bytes),base=JSON.parse(REGIONAL_SCHEMA),expected=verify(REGIONAL_SCHEMA);
 for(const bytes of [Buffer.from(JSON.stringify(reorderSchemaObjects(base))),Buffer.from('\r\n '+JSON.stringify(reorderSchemaObjects(base),null,4)+'\t\n')])assert.deepEqual(verify(bytes),expected);
 const mutations=[v=>v.components.schemas.WanVace14bInpaintingInput.properties.seed.title+=' changed',v=>delete v.components.schemas.WanVace14bInpaintingInput.properties.seed,v=>v.added_property=true,v=>v.components.schemas.WanVace14bInpaintingInput.properties.enable_safety_checker.default='changed',v=>v.components.schemas.WanVace14bInpaintingInput.properties.resolution.enum.push('unreviewed'),v=>v.components.schemas.WanVace14bInpaintingInput['x-fal-order-properties'].reverse(),v=>v.paths['/'+VACE].post.requestBody.content['application/json'].schema.$ref+='Changed'];
 for(const change of mutations){const changed=structuredClone(base);change(changed);assert.throws(()=>verify(Buffer.from(JSON.stringify(changed))),{code:'PRICE_NOT_VERIFIABLE'});}
 const raw=REGIONAL_SCHEMA.toString();
 // Actual JSON own-property, not the special JS object-literal setter.
 assert.throws(()=>verify(Buffer.from('{"__proto__":{"schemaShadow":true},'+raw.slice(1))),{code:'PRICE_NOT_VERIFIABLE'});
 for(const key of ['openapi','\\u006fpenapi'])assert.throws(()=>verify(Buffer.from('{"'+key+'":'+JSON.stringify(base.openapi)+','+raw.slice(1))),{code:'PRICE_NOT_VERIFIABLE'});
 assert.throws(()=>verify(Buffer.from(raw.replace('"type":"string"','"type":"string","type":"string"'))),{code:'PRICE_NOT_VERIFIABLE'});
});

test('regional schema strict JSON guard rejects ambiguity without flagging strings or independent objects',async t=>{
 // Export a private helper only in a TEMP test copy; no production API/flag.
 const temp=fs.mkdtempSync(path.join(os.tmpdir(),'regional-schema-guard-'));t.after(()=>{assert.equal(path.dirname(path.resolve(temp)),path.resolve(os.tmpdir()));assert.ok(path.basename(temp).startsWith('regional-schema-guard-'));fs.rmSync(temp,{recursive:true});});
 const source=fs.readFileSync(new URL('./fal_sheet_transport.mjs',import.meta.url),'utf8').replace('"./sheet_video_metadata.mjs"',JSON.stringify(new URL('./sheet_video_metadata.mjs',import.meta.url).href));
 const moduleFile=path.join(temp,'transport.mjs');fs.writeFileSync(moduleFile,source+'\nexport {regionalSchemaDocument};\n');const {regionalSchemaDocument:parse}=await import(pathToFileURL(moduleFile));
 const valid=JSON.stringify({a:1,nested:{a:2},items:[{a:3},{a:4}],text:'{"a":1,"a":2} [ ] : "quoted" \\ tail 1e400 -1e400 1e-400 1.00000000000000001'});assert.deepEqual(parse(Buffer.from(valid)),JSON.parse(valid));
 const own=parse(Buffer.from('{"__proto__":{"own":true},"constructor":1}'));assert.ok(Object.hasOwn(own,'__proto__'));assert.equal(own.__proto__.own,true);assert.equal(Object.getPrototypeOf(own),Object.prototype);
 for(const raw of ['{"a":1,"a":2}','{"a":1,"\\u0061":1}','{"nested":{"a":1,"\\u0061":1}}','{"n":1e400}','{"n":-1e400}','{"n":NaN}','{"n":Infinity}','{"a":}','{"a":1} trailing'])assert.throws(()=>parse(Buffer.from(raw)),{code:'PRICE_NOT_VERIFIABLE'});
 assert.throws(()=>parse(Buffer.from([0xff])),{code:'PRICE_NOT_VERIFIABLE'});assert.throws(()=>parse(Buffer.alloc(5*1024*1024+1,32)),{code:'PRICE_NOT_VERIFIABLE'});
});

